import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { gunzipSync } from 'node:zlib';
import { previewLegacyRule2Migration } from '../src/planner/attempts/persistence/legacyPreview.ts';
import { replayStateRule2 } from '../src/planner/attempts/persistence/codec.ts';

// Byte-for-byte archived PR1 independent audit evidence, generated by the
// frozen rule1 parent BEFORE PR2 existed. Never regenerate with PR2 code.
const evidence = JSON.parse(gunzipSync(readFileSync(new URL('./fixtures/persistence-rule1-pr1-audit.json.gz', import.meta.url))));
for (const f of evidence.fixtures.filter(f => ['complete', 'corrections'].includes(f.variant))) {
  test(`${f.name}: frozen independent all-value H2/R2 oracle, deleted TODO, Undo and corrections`, async () => {
    const p = await previewLegacyRule2Migration(f.state1Raw);
    assert.equal(p.status, 'preview'); assert.equal(p.analysis.originalDigest, f.digest1);
    assert.deepEqual(p.candidate, f.state2);
    assert.deepEqual(p.analysis.r2, f.required2);
    assert.deepEqual((await replayStateRule2(p.candidate)).workspace, f.workspace);
    if (f.name === '23-corrections') {
      assert.equal(p.candidate.corrections.length, 2);
      assert.deepEqual(p.candidate.corrections, JSON.parse(f.state1Raw).corrections);
    }
    if (f.name === '23-corrections') assert.ok(p.analysis.legalLegacyNonUuid.length > 0, 'inherited source nonUUID kept');
  });
}
